@php $recentStatusLabels = \App\Services\DesignTaskStatusService::STATUSES; @endphp
@forelse($recentTasks as $task)@php $isOverdue = $task->status !== 'completed' && $task->due_at && $task->due_at->isPast(); @endphp<tr><td><a class="file-link" style="white-space:nowrap" href="{{ route('admin.tasks.show',$task) }}">{{ $task->task_id }}</a><div style="margin-top:3px;font-weight:700;display:flex;align-items:center;gap:6px;flex-wrap:wrap"><span>{{ $task->task_name }}</span>@if($task->priority)<span class="badge priority-{{ $task->priority }}">{{ $task->priority }}</span>@endif</div></td><td>{{ $task->designer?->name ?? '—' }}</td><td><span class="badge badge-dark">{{ $recentStatusLabels[$task->status] ?? ucwords(str_replace('_',' ',$task->status)) }}</span></td><td style="white-space:nowrap{{ $isOverdue ? ';color:#b42318;font-weight:750' : '' }}">{{ $task->due_at?->format('d M Y · h:i A') }}@if($isOverdue)<div style="margin-top:4px"><span class="badge badge-danger">Overdue</span></div>@endif</td></tr>@empty<tr><td colspan="4" class="empty-state">{{ ($search ?? '') !== '' ? 'No matching tasks found.' : 'No tasks available.' }}</td></tr>@endforelse
